parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "respuesta": {
      "type": "string",
      "description": "Texto para el cliente, corto, para WhatsApp"
    },
    "accion": {
      "type": "string",
      "enum": [
        "responder",
        "derivar_humano"
      ]
    },
    "motivo": {
      "type": "string",
      "enum": [
        "ninguno",
        "pedido",
        "reclamo",
        "sin_informacion",
        "pide_persona"
      ]
    },
    "fuentes": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Ids de los fragmentos usados, por ejemplo kb-05"
    }
  },
  "required": [
    "respuesta",
    "accion",
    "motivo",
    "fuentes"
  ]
}

